import { DomainError } from "../domain/DomainError";
import { TaskRepository } from "../domain/Repositories";
import { TaskDto, toTaskDto } from "./TaskDtos";

export class MarkTaskDoneUseCase {
  public constructor(private readonly tasks: TaskRepository) {}

  public execute(taskId: string): TaskDto {
    const task = this.tasks.findById(taskId);
    if (!task) {
      throw new DomainError("Task does not exist");
    }
    task.markDone();
    this.tasks.save(task);
    return toTaskDto(task);
  }
}

